/* generated by tools/lite.js - do not edit. The questions (and sets) that the quant lessons quiz blocks use. */
QB.add([
  {"id":"number-system-01","sec":"quant","topic":"number-system","pattern":"divisibility-rules","d":"Easy","q":"Which digit should replace * so that the number **7*35** is divisible by 9?","opts":["1","3","6","9"],"ans":1,"time":40,"sol":["A number is divisible by 9 when its digit sum is a multiple of 9","7 + * + 3 + 5 = 15 + *","The next multiple of 9 is 18, so * = **3**"],"short":"Digit sum 15 needs 3 more to reach 18.","trap":"Using the rule for 3 (any multiple of 3 works) instead of 9.","why":["Digit sum 16 is not a multiple of 9",null,"Digit sum 21 is divisible by 3, not by 9","Digit sum 24 is divisible by 3, not by 9"],"calc":"3"},
  {"id":"number-system-02","sec":"quant","topic":"number-system","pattern":"unit-digit-by-cyclicity","d":"Easy","q":"What is the unit digit of **3⁵⁸**?","opts":["9","3","7","1"],"ans":0,"time":45,"sol":["Unit digits of powers of 3 repeat every 4: 3, 9, 7, 1","58 ÷ 4 leaves remainder 2","The 2nd digit in the cycle is **9**"],"short":"Divide the power by 4 and read the cycle; remainder 0 means the 4th digit.","trap":"Using the quotient instead of the remainder, or mixing up remainder 0 and 2.","why":[null,"Took remainder 1 instead of 2","Took remainder 3 instead of 2","Treated the exponent as a multiple of 4"],"calc":"Number(3n**58n%10n)"},
  {"id":"number-system-05","sec":"quant","topic":"number-system","pattern":"remainders-of-large-powers","d":"Medium","q":"What is the remainder when **2¹⁰⁰** is divided by **7**?","opts":["1","4","2","6"],"ans":2,"time":70,"sol":["2³ = 8 leaves remainder 1 on division by 7","100 = 3 × 33 + 1, so 2¹⁰⁰ = (2³)³³ × 2","Remainder = 1 × 2 = **2**"],"short":"Find the power that gives remainder 1, then multiply by what is left over.","trap":"Reading 100 as a multiple of 3 and answering 1.","why":["Treated 100 as a multiple of 3","Took the exponent remainder as 2, giving 2²",null,"Wrote the remainder as −1, i.e. 6"],"calc":"Number(2n**100n%7n)"},
  {"id":"number-system-06","sec":"quant","topic":"number-system","pattern":"factors-count-sum-even-odd","d":"Medium","q":"How many factors of **360** are perfect squares?","opts":["6","8","24","4"],"ans":3,"time":75,"sol":["360 = 2³ × 3² × 5","A square factor needs even powers: 2⁰ or 2², 3⁰ or 3², 5⁰","2 × 2 × 1 = **4** (they are 1, 4, 9, 36)"],"short":"Count only even exponents (0, 2, …) in each prime.","trap":"Counting all factors (24) or letting 5 appear to the power 1.","why":["Counted odd factors instead","Allowed the odd power 5¹ as well","Counted all factors of 360",null],"calc":"Array.from({length:360},(_,i)=>i+1).filter(n=>360%n===0&&Number.isInteger(sqrt(n))).length"},
  {"id":"number-system-08","sec":"quant","topic":"number-system","pattern":"trailing-zeros-in-n","d":"Hard","q":"How many zeros are at the end of **1000!**?","opts":["200","248","249","250"],"ans":2,"time":80,"sol":["Zeros = number of 5s: ⌊1000/5⌋ + ⌊1000/25⌋ + ⌊1000/125⌋ + ⌊1000/625⌋","200 + 40 + 8 + 1","= **249**"],"short":"Keep dividing by 5 and add the quotients.","trap":"Stopping at 5³ and missing the 625 term, or stopping at 1000 ÷ 5.","why":["Counted only multiples of 5","Missed the multiples of 625",null,"Rounded 1.6 up to 2 for the last term"],"calc":"200+40+8+1"},
  {"id":"hcf-lcm-01","sec":"quant","topic":"hcf-lcm","pattern":"hcf-lcm-by-prime-factors","d":"Easy","q":"Find the HCF of **84** and **126**.","opts":["6","21","42","252"],"ans":2,"time":40,"sol":["84 = 2² × 3 × 7 and 126 = 2 × 3² × 7","Take the lowest power of each common prime: 2 × 3 × 7","HCF = **42**"],"short":"Divide the bigger by the smaller: 126 − 84 = 42, and 42 divides 84.","trap":"Giving the LCM (252) or stopping at a common factor.","why":["A common factor, not the greatest","A common factor, not the greatest",null,"That is the LCM"],"calc":"gcd(84,126)"},
  {"id":"hcf-lcm-03","sec":"quant","topic":"hcf-lcm","pattern":"bells-traffic-lights-together","d":"Easy","q":"Three bells ring at intervals of **10, 15 and 20 minutes**. They ring together at 9:00 a.m. After how many minutes will they next ring together?","opts":["60","5","30","45"],"ans":0,"time":45,"sol":["Next common time = LCM of 10, 15, 20","LCM = 2² × 3 × 5 = **60 minutes**"],"short":"LCM of the intervals.","trap":"Taking the LCM of only two of the three, or adding the intervals.","why":[null,"That is the HCF","LCM of just 10 and 15","Added 10 + 15 + 20"],"calc":"lcm(lcm(10,15),20)"},
  {"id":"hcf-lcm-04","sec":"quant","topic":"hcf-lcm","pattern":"greatest-number-leaving-given-remainders","d":"Medium","q":"Find the greatest number that divides **154** and **216**, leaving remainders **4** and **6** respectively.","opts":["2","10","30","150"],"ans":2,"time":65,"sol":["Subtract the remainders: 154 − 4 = 150 and 216 − 6 = 210","The number must divide both exactly, so take HCF(150, 210)","HCF = **30**"],"short":"Subtract the remainders first, then take the HCF.","trap":"Taking the HCF of 154 and 216 without subtracting the remainders.","why":["HCF of 154 and 216 without subtracting","A common factor, not the greatest",null,"Stopped at the first reduced number"],"calc":"gcd(154-4,216-6)"},
  {"id":"hcf-lcm-05","sec":"quant","topic":"hcf-lcm","pattern":"least-number-leaving-given-remainders","d":"Medium","q":"Find the least number which leaves remainder **5** when divided by each of **12, 16 and 18**.","opts":["149","139","144","293"],"ans":0,"time":65,"sol":["LCM of 12, 16, 18 = 144","The same remainder 5 is added on top of the LCM","Number = 144 + 5 = **149**"],"short":"Same remainder every time: LCM + remainder.","trap":"Giving the LCM itself, or subtracting the remainder.","why":[null,"Subtracted 5 instead of adding","That is the LCM, which leaves remainder 0","Took 2 × LCM + 5, which is not the least"],"calc":"lcm(lcm(12,16),18)+5"},
  {"id":"hcf-lcm-07","sec":"quant","topic":"hcf-lcm","pattern":"tiles-rows-cutting-into-equal","d":"Medium","q":"A hall floor measures **7 m 20 cm** by **5 m 40 cm**. It is to be covered with identical square tiles of the largest possible size with no cutting. How many tiles are needed?","opts":["7","12","108","3,888"],"ans":1,"time":80,"sol":["Sides in cm: 720 and 540","Largest tile side = HCF(720, 540) = 180 cm","Tiles = (720 ÷ 180) × (540 ÷ 180) = 4 × 3 = **12**"],"short":"Largest square tile = HCF of the two sides; then count along each side.","trap":"Adding 4 + 3 or using a tile smaller than the greatest.","why":["Added the two counts instead of multiplying",null,"Used a 60 cm tile, a common factor but not the greatest","Used a 10 cm tile"],"calc":"(720/gcd(720,540))*(540/gcd(720,540))"},
  {"id":"simplification-01","sec":"quant","topic":"simplification","pattern":"bodmas","d":"Easy","q":"Simplify: **48 ÷ 6 × 2 + 3² − 4**","opts":["21","9","15","25"],"ans":0,"time":45,"sol":["Orders first: 3² = 9","Division and multiplication, left to right: 48 ÷ 6 = 8, 8 × 2 = 16","16 + 9 − 4 = **21**"],"short":"Index, then ÷ and × from the left, then + and −.","trap":"Doing 6 × 2 before the division.","why":[null,"Did 6 × 2 = 12 first, then 48 ÷ 12 = 4","Read 3² as 3","Forgot to subtract 4"],"calc":"48/6*2+9-4"},
  {"id":"simplification-03","sec":"quant","topic":"simplification","pattern":"approximation","d":"Easy","q":"Find the approximate value: **√624.9 × 3.98 ≈ ?**","opts":["80","100","125","150"],"ans":1,"time":40,"sol":["√624.9 ≈ √625 = 25","3.98 ≈ 4","25 × 4 = **100**"],"short":"Round to the nearest friendly number first: 625 = 25², 3.98 ≈ 4.","trap":"Using the number 62.49 or treating √625 as 125.","why":["√625 taken as 20",null,"Used 625 ÷ 5 = 125 as the root","Used 625 ÷ 4 as a rough root"],"calc":"sqrt(625)*4"},
  {"id":"simplification-04","sec":"quant","topic":"simplification","pattern":"fractions-and-decimals","d":"Medium","q":"Find the value of **0.4545… × 22**, where 0.4545… is the recurring decimal 0.4̄5̄.","opts":["9.9","12.1","10","48.4"],"ans":2,"time":65,"sol":["0.4̄5̄ = 45/99 = 5/11","5/11 × 22 = **10**"],"short":"Recurring two-digit decimals = the digits over 99.","trap":"Using 0.45 as an exact decimal.","why":["Used 0.45 instead of 0.4545…","Used 0.55 (the complement) by mistake",null,"Inverted the fraction"],"calc":"45/99*22"},
  {"id":"simplification-05","sec":"quant","topic":"simplification","pattern":"surds-and-indices","d":"Medium","q":"Simplify: **8^(2/3) × 9^(3/2) ÷ 16^(1/2)**","opts":["6.75","13.5","81","27"],"ans":3,"time":70,"sol":["8^(2/3) = (∛8)² = 4, and 9^(3/2) = (√9)³ = 27","16^(1/2) = 4","4 × 27 ÷ 4 = **27**"],"short":"Root first, then power: a^(m/n) = (ⁿ√a)ᵐ.","trap":"Treating a fractional power as a plain multiplier.","why":["Used 16 instead of 16^(1/2)","Took 8^(2/3) as 2","Took 9^(3/2) as 9², i.e. 81",null],"calc":"8**(2/3)*9**1.5/16**0.5"},
  {"id":"simplification-06","sec":"quant","topic":"simplification","pattern":"square-cube-roots","d":"Medium","q":"Evaluate: **√0.0169 + ∛0.000343**","opts":["0.2","0.02","0.83","1.37"],"ans":0,"time":65,"sol":["√0.0169 = 0.13, because 13² = 169 and 4 decimal places halve to 2","∛0.000343 = 0.07, because 7³ = 343 and 6 decimal places become 2","0.13 + 0.07 = **0.2**"],"short":"Square roots halve the decimal places, cube roots divide them by three.","trap":"Placing the decimal point in the wrong spot.","why":[null,"Decimal slip: 0.013 + 0.007","Took ∛0.000343 as 0.7","Took √0.0169 as 1.3"],"calc":"0.13+0.07"},
  {"id":"profit-loss-01","sec":"quant","topic":"profit-loss","pattern":"basic-profit-loss-pct","d":"Easy","q":"A trader buys a bag for ₹640 and sells it for ₹720. What is his profit percent?","opts":["12.5%","11.11%","80%","112.5%"],"ans":0,"time":40,"sol":["Profit = 720 − 640 = ₹80","Profit % = 80 ÷ 640 × 100 = **12.5%**"],"short":"Profit % is always on the cost price: 80/640 = 1/8.","trap":"Dividing the profit by the selling price (80/720).","why":[null,"Divided by the selling price","Gave the rupee profit as a percent","Gave SP as a percent of CP"],"calc":"80/640*100"},
  {"id":"profit-loss-03","sec":"quant","topic":"profit-loss","pattern":"marked-price-and-discount","d":"Easy","q":"A shirt is marked at ₹800 and a discount of **15%** is given. What is the selling price?","opts":["₹120","₹680","₹785","₹920"],"ans":1,"time":35,"sol":["Discount = 15% of 800 = ₹120","SP = 800 − 120 = **₹680**"],"short":"Pay 85% of the marked price: 0.85 × 800.","trap":"Giving the discount amount, or subtracting 15 rupees.","why":["That is the discount, not the price",null,"Subtracted ₹15 instead of 15%","Added the discount instead of subtracting"],"calc":"800*0.85"},
  {"id":"profit-loss-04","sec":"quant","topic":"profit-loss","pattern":"successive-discounts","d":"Medium","q":"An item marked ₹2,500 is given successive discounts of **20%** and **10%**. How much more does the customer pay than if a flat **30%** discount were given?","opts":["₹50","₹0","₹75","₹250"],"ans":0,"time":65,"sol":["Successive: 2,500 × 0.8 × 0.9 = ₹1,800","Flat 30%: 2,500 × 0.7 = ₹1,750","Difference = **₹50**"],"short":"Two discounts a% and b% are worth less than a + b: they equal a + b − ab/100 = 28%.","trap":"Adding the two discounts as if they were one.","why":[null,"Assumed the two are the same","Gap of 3% instead of 2%","Took the last 10% discount amount"],"calc":"2500*0.8*0.9-2500*0.7"},
  {"id":"profit-loss-06","sec":"quant","topic":"profit-loss","pattern":"two-items-at-the-same","d":"Medium","q":"A shopkeeper sells two watches at ₹1,980 each. On one he gains **10%** and on the other he loses **10%**. What is his overall loss in rupees (₹0 if none)?","opts":["₹0","₹40","₹198","₹400"],"ans":1,"time":70,"sol":["Gain watch: CP = 1,980 ÷ 1.1 = ₹1,800","Loss watch: CP = 1,980 ÷ 0.9 = ₹2,200","Total CP 4,000, total SP 3,960: **loss of ₹40**"],"short":"Equal SP with x% gain and x% loss always gives a loss of x²/100 % of the total CP: 1% of 4,000.","trap":"Assuming the gain and loss cancel.","why":["Assumed 10% gain and 10% loss cancel",null,"Took 10% of one selling price","Decimal slip"],"calc":"(1980/1.1+1980/0.9)-1980*2"},
  {"id":"profit-loss-07","sec":"quant","topic":"profit-loss","pattern":"dishonest-dealer-false-weights","d":"Hard","q":"A shopkeeper marks his goods **20%** above cost, allows a **10%** discount, and also uses a **900 g** weight for a kilogram. What is his overall profit percent?","opts":["8%","11.11%","20%","19.11%"],"ans":2,"time":100,"sol":["Let the cost of 1 kg be ₹100. He charges 1.2 × 0.9 × 100 = ₹108 for 900 g","Real cost of 900 g = ₹90","Profit = (108 − 90) ÷ 90 × 100 = **20%**"],"short":"Cost of what is really handed over is the base: 900 g, not 1 kg.","trap":"Adding the 8% price gain and the 11.11% weight gain.","why":["Ignored the false weight","Counted only the false weight",null,"Added the two gains"],"calc":"(1.2*0.9-0.9)/0.9*100"},
  {"id":"interest-01","sec":"quant","topic":"interest","pattern":"si-basics-find-p-r","d":"Easy","q":"Find the simple interest on ₹8,000 at **7.5%** per annum for **4 years**.","opts":["₹600","₹10,400","₹24,000","₹2,400"],"ans":3,"time":40,"sol":["SI = P × R × T ÷ 100","= 8,000 × 7.5 × 4 ÷ 100 = **₹2,400**"],"short":"1% of 8,000 is 80, so 7.5% is 600 a year; times 4.","trap":"Giving the amount instead of the interest, or one year only.","why":["Gave a single year's interest","Gave the amount (P + SI)","Decimal slip",null],"calc":"8000*7.5*4/100"},
  {"id":"interest-03","sec":"quant","topic":"interest","pattern":"ci-annual","d":"Easy","q":"What is the compound interest on ₹10,000 for **2 years** at **10%** per annum, compounded annually?","opts":["₹1,000","₹2,000","₹2,100","₹12,100"],"ans":2,"time":45,"sol":["Year 1: 10% of 10,000 = 1,000","Year 2: 10% of 11,000 = 1,100","CI = 1,000 + 1,100 = **₹2,100**"],"short":"Two years at 10%: 10 + 10 + 1 = 21%.","trap":"Giving the amount (₹12,100) or the simple interest (₹2,000).","why":["One year's interest only","That is the simple interest",null,"That is the amount, not the interest"],"calc":"10000*1.1*1.1-10000"},
  {"id":"interest-04","sec":"quant","topic":"interest","pattern":"ci-half-yearly-and-quarterly","d":"Medium","q":"What is the amount on ₹16,000 for **1½ years** at **20%** per annum, compounded half-yearly?","opts":["₹21,296","₹20,800","₹21,120","₹5,296"],"ans":0,"time":75,"sol":["Rate per half-year = 10%, number of half-years = 3","Amount = 16,000 × 1.1³ = 16,000 × 1.331","= **₹21,296**"],"short":"Halve the rate, double the periods.","trap":"Giving the interest, or compounding annually and adding simple interest for the half year.","why":[null,"Simple interest on the full term","Compounded once for a year, then simple for half a year","That is the interest, not the amount"],"calc":"16000*1.1**3"},
  {"id":"interest-06","sec":"quant","topic":"interest","pattern":"becomes-n-times-doubling","d":"Medium","q":"A sum of money doubles itself in **8 years** at simple interest. In how many years will it become **5 times** itself?","opts":["24","32","40","48"],"ans":1,"time":60,"sol":["Doubling means the interest equals the principal in 8 years","To become 5 times, interest must be 4 times the principal","Time = 4 × 8 = **32 years**"],"short":"Becoming n times needs (n − 1) times the doubling time.","trap":"Multiplying 8 by 5.","why":["Used 3 × 8 (that is 4 times the sum)",null,"Multiplied 8 by 5","Used 6 × 8"],"calc":"4*8"},
  {"id":"interest-09","sec":"quant","topic":"interest","pattern":"equal-instalments","d":"Hard","q":"A loan is repaid in **two equal annual instalments of ₹4,840** each, the first due at the end of year 1. Interest is **10% per annum**, compounded annually. What was the loan?","opts":["₹8,000","₹8,400","₹8,800","₹9,680"],"ans":1,"time":100,"sol":["Loan = present value of both payments","4,840 ÷ 1.1 + 4,840 ÷ 1.1² = 4,400 + 4,000","Loan = **₹8,400**"],"short":"Discount each instalment back to today: first by 1.1, second by 1.21.","trap":"Adding the instalments, or discounting both by two years.","why":["Discounted the total of both by 2 years",null,"Discounted both instalments by only one year","Added the instalments without discounting"],"calc":"4840/1.1+4840/1.21"},
  {"id":"ratio-01","sec":"quant","topic":"ratio","pattern":"ratio-basics","d":"Easy","q":"Two numbers are in the ratio **7 : 9** and their difference is **24**. Find the larger number.","opts":["84","96","216","108"],"ans":3,"time":45,"sol":["Difference = 9k − 7k = 2k = 24, so k = 12","Larger = 9 × 12 = **108**"],"short":"Match the difference of the ratio parts with the actual difference.","trap":"Using 24 itself as one unit.","why":["That is the smaller number","Used k = 12 with 8 parts","Used 24 as one part",null],"calc":"9*24/2"},
  {"id":"ratio-02","sec":"quant","topic":"ratio","pattern":"dividing-an-amount","d":"Easy","q":"₹1,35,000 is divided among A, B and C in the ratio **2 : 3 : 4**. How much does C get?","opts":["₹30,000","₹60,000","₹45,000","₹67,500"],"ans":1,"time":40,"sol":["Total parts = 2 + 3 + 4 = 9","One part = 1,35,000 ÷ 9 = ₹15,000","C = 4 × 15,000 = **₹60,000**"],"short":"C's share is 4/9 of the total.","trap":"Dividing by 2 or giving another person's share.","why":["That is A's share",null,"That is B's share","Took C as half the total"],"calc":"135000*4/9"},
  {"id":"ratio-04","sec":"quant","topic":"ratio","pattern":"combining-ratios","d":"Medium","q":"A : B = 2 : 3 and B : C = 4 : 5. If A + B + C = ₹7,000, how much is C?","opts":["₹1,400","₹2,500","₹3,500","₹3,000"],"ans":3,"time":75,"sol":["Make B equal: A : B = 8 : 12 and B : C = 12 : 15","A : B : C = 8 : 12 : 15, total 35 parts","C = 15 ÷ 35 × 7,000 = **₹3,000**"],"short":"Scale each ratio so the common term matches (LCM of 3 and 4 = 12).","trap":"Joining 2 : 3 and 4 : 5 without matching B.","why":["Wrote 8 : 12 : 5 by not scaling C","Added 2 + 3 + 4 + 5 = 14 parts","Wrote the ratio as 2 : 3 : 5",null],"calc":"7000*15/35"},
  {"id":"ratio-07","sec":"quant","topic":"ratio","pattern":"income-and-expenditure-ratios","d":"Hard","q":"The incomes of A and B are in the ratio **5 : 4** and their expenditures are in the ratio **3 : 2**. If each saves ₹1,600, find A's income.","opts":["₹4,000","₹2,400","₹3,200","₹8,000"],"ans":0,"time":110,"sol":["Incomes 5x and 4x, expenditures 3y and 2y","5x − 3y = 1,600 and 4x − 2y = 1,600; eliminating y gives x = 800","A's income = 5 × 800 = **₹4,000**"],"short":"Savings = income − expenditure; two equations, two unknowns.","trap":"Reading 1,600 as one unit of income.","why":[null,"That is A's expenditure","That is B's income","Took 1,600 as x"],"calc":"5*800"},
  {"id":"ratio-09","sec":"quant","topic":"ratio","pattern":"direct-and-inverse-variation","d":"Medium","q":"Food for **120** soldiers lasts **30 days**. After **10 days**, **40** soldiers leave. For how many more days will the remaining food last the remaining soldiers?","opts":["20","30","40","45"],"ans":1,"time":80,"sol":["After 10 days the food left is 20 days' worth for 120 soldiers","Now 80 soldiers: more days is inverse, 20 × 120 ÷ 80","= **30 days**"],"short":"Fewer people means the same food lasts longer: days ∝ 1/people.","trap":"Using the full 30 days as the food left.","why":["Ignored the soldiers leaving",null,"Added the 10 days already passed","Used 30 × 120 ÷ 80 and ignored the 10 days used"],"calc":"20*120/80"},
  {"id":"partnership-01","sec":"quant","topic":"partnership","pattern":"equal-time","d":"Easy","q":"A and B start a business with ₹30,000 and ₹50,000 and run it for a year. The profit is ₹24,000. What is A's share?","opts":["₹15,000","₹12,000","₹9,000","₹14,400"],"ans":2,"time":38,"sol":["Ratio of investments = 30 : 50 = 3 : 5","A's share = 3/8 × 24,000 = **₹9,000**"],"short":"Reduce the ratio first (3:5), then divide the profit in 8 parts.","trap":"Taking 3/5 of the profit because the ratio has a 5 in it; the total parts are 3 + 5 = 8.","why":["Gave B's share","Split the profit equally",null,"Took 3/5 of the profit instead of 3/8"],"calc":"24000*3/8"},
  {"id":"partnership-04","sec":"quant","topic":"partnership","pattern":"different-times","d":"Medium","q":"A invests ₹20,000 for the whole year. B joins after 6 months with ₹30,000. At the end of the year the profit is ₹28,000. What is B's share?","opts":["₹16,000","₹14,000","₹12,000","₹16,800"],"ans":2,"time":60,"sol":["A: 20,000 × 12 = 2,40,000; B: 30,000 × 6 = 1,80,000","Ratio = 4 : 3 (7 parts)","B's share = 3/7 × 28,000 = **₹12,000**"],"short":"Profit is shared in capital × months, not capital alone.","trap":"Forgetting that B was in the business for only 6 months.","why":["Gave A's share","Split equally, ignoring the investments",null,"Ignored the time and used 2 : 3"],"calc":"28000*180000/(240000+180000)"},
  {"id":"partnership-06","sec":"quant","topic":"partnership","pattern":"working-partner-s-salary","d":"Medium","q":"A and B invest ₹40,000 and ₹60,000 for a year. A manages the firm and gets **10%** of the profit as his fee; the rest is shared in the ratio of capital. If the profit is ₹50,000, how much does A get in all?","opts":["₹20,000","₹18,000","₹27,000","₹23,000"],"ans":3,"time":60,"sol":["Fee = 10% of 50,000 = ₹5,000; the rest = ₹45,000","Ratio 40 : 60 = 2 : 3, so A's part = 2/5 × 45,000 = 18,000","A's total = 5,000 + 18,000 = **₹23,000**"],"short":"Pay the fee first, then split what is left.","trap":"Splitting the full profit in the capital ratio and then adding the fee.","why":["Ignored the fee and used 2/5 of the whole profit","Gave A's share of the rest but forgot the fee","Gave B's total",null],"calc":"5000+45000*2/5"},
  {"id":"partnership-08","sec":"quant","topic":"partnership","pattern":"investment-changed-midway","d":"Medium","q":"A starts with ₹50,000 and withdraws ₹10,000 after 4 months. B invests ₹40,000 for the full year. The yearly profit is ₹45,000. What is A's share?","opts":["₹25,000","₹21,600","₹23,400","₹22,500"],"ans":2,"time":60,"sol":["A: 50,000 × 4 + 40,000 × 8 = 2,00,000 + 3,20,000 = 5,20,000","B: 40,000 × 12 = 4,80,000","Ratio = 13 : 12, so A = 13/25 × 45,000 = **₹23,400**"],"short":"Add up capital × time for each stretch where the capital was different.","trap":"Using the starting capital for all 12 months.","why":["Ignored the withdrawal (50 : 40 = 5 : 4)","Gave B's share",null,"Split the profit equally"],"calc":"45000*520000/(520000+480000)"},
  {"id":"partnership-09","sec":"quant","topic":"partnership","pattern":"investment-changed-midway","d":"Hard","q":"A invests ₹45,000 for the full year. B joins 3 months later. At the end of the year the profit is divided between A and B in the ratio 3 : 2. How much did B invest?","opts":["₹30,000","₹40,000","₹90,000","₹1,20,000"],"ans":1,"time":95,"sol":["B was in for 12 − 3 = 9 months","45,000 × 12 : B × 9 = 3 : 2","B × 9 = 5,40,000 × 2/3 = 3,60,000, so B = **₹40,000**"],"short":"Equate the capital-time products to the ratio and solve for B.","trap":"Using the months before B joined instead of the months after.","why":["Used 12 months for B",null,"Inverted the ratio (gave B the 3)","Used 3 months (the delay) as B's time"],"calc":"45000*12*2/3/9"},
  {"id":"mixtures-01","sec":"quant","topic":"mixtures","pattern":"alligation","d":"Easy","q":"Rice costing ₹40 per kg is mixed with rice costing ₹60 per kg in the ratio 3 : 2. What is the cost of the mixture per kg?","opts":["₹50","₹52","₹48","₹44"],"ans":2,"time":38,"sol":["Total cost for 5 kg = 3 × 40 + 2 × 60 = 240","Mean price = 240 ÷ 5 = **₹48**"],"short":"The mean lies closer to the bigger quantity: 40 + 20 × 2/5.","trap":"Averaging the two prices without weighting by quantity.","why":["Took the simple average of 40 and 60","Swapped the ratio (2 : 3)",null,"Took 1/5 of the gap instead of 2/5"],"calc":"(3*40+2*60)/5"},
  {"id":"mixtures-03","sec":"quant","topic":"mixtures","pattern":"mixing-two-solutions-to-a","d":"Easy","q":"4 litres of a 25% acid solution are mixed with 6 litres of a 15% acid solution. What is the percentage of acid in the mixture?","opts":["20%","19%","21%","40%"],"ans":1,"time":38,"sol":["Acid = 25% of 4 + 15% of 6 = 1 + 0.9 = 1.9 L","Concentration = 1.9 ÷ 10 = **19%**"],"short":"Weighted average: (4 × 25 + 6 × 15) ÷ 10.","trap":"Ignoring that more of the weaker solution is used.","why":["Took the simple average of 25% and 15%",null,"Swapped the weights (6 L at 25%, 4 L at 15%)","Added 25 and 15"],"calc":"(4*25+6*15)/10"},
  {"id":"mixtures-04","sec":"quant","topic":"mixtures","pattern":"repeated-replacement","d":"Medium","q":"A vessel holds 40 litres of pure milk. 8 litres are drawn out and replaced with water, and then the same is done once more. How much milk is now in the vessel?","opts":["24 L","25.6 L","14.4 L","32 L"],"ans":1,"time":60,"sol":["Each step keeps (40 − 8) ÷ 40 = 4/5 of the milk","Milk = 40 × 4/5 × 4/5 = **25.6 L**"],"short":"Final = Original × (1 − x/total)ⁿ.","trap":"Taking the second 8 litres as pure milk; part of it is already water.","why":["Subtracted 8 twice and then another 8 for water (linear)",null,"Gave the quantity of water","Stopped after the first replacement"],"calc":"40*0.8*0.8"},
  {"id":"mixtures-05","sec":"quant","topic":"mixtures","pattern":"removing-and-adding-water","d":"Medium","q":"A 60-litre mixture of milk and water is in the ratio 3 : 1. How much water must be added to make the ratio 1 : 1?","opts":["30 L","15 L","45 L","60 L"],"ans":0,"time":60,"sol":["Milk = 3/4 × 60 = 45 L, water = 15 L","For 1 : 1, water must also be 45 L","Add 45 − 15 = **30 L**"],"short":"Milk never changes, so match water to the milk quantity.","trap":"Adding the original water quantity, or the milk quantity, instead of the difference.","why":[null,"Gave the water already present","Gave the quantity of milk","Doubled the mixture"],"calc":"45-15"},
  {"id":"mixtures-07","sec":"quant","topic":"mixtures","pattern":"three-mixtures","d":"Medium","q":"Three solutions with 20%, 30% and 50% salt are mixed in volumes of 10 L, 20 L and 20 L. What is the percentage of salt in the final mixture?","opts":["33.3%","36%","35%","40%"],"ans":1,"time":60,"sol":["Salt = 2 + 6 + 10 = 18 L","Total volume = 50 L","Concentration = 18 ÷ 50 = **36%**"],"short":"Add the salt litres, divide by the total litres.","trap":"Averaging the three percentages without volumes.","why":["Took the simple average of 20, 30 and 50",null,"Averaged only the 20% and 50% solutions","Averaged only the 30% and 50% solutions"],"calc":"(10*20+20*30+20*50)/50"},
  {"id":"averages-01","sec":"quant","topic":"averages","pattern":"basic-averages","d":"Easy","q":"What is the average of 12, 18, 25, 31 and 44?","opts":["130","25","26","29.5"],"ans":2,"time":38,"sol":["Sum = 12 + 18 + 25 + 31 + 44 = 130","Average = 130 ÷ 5 = **26**"],"short":"Add and divide by how many numbers there are.","trap":"Giving the sum, or the median, as the average.","why":["Gave the sum","Gave the middle value",null,"Left out 12 and divided by 4"],"calc":"(12+18+25+31+44)/5"},
  {"id":"averages-03","sec":"quant","topic":"averages","pattern":"cricket-averages","d":"Easy","q":"A batter's average after 9 innings is 32. He scores 62 in the 10th innings. What is his new average?","opts":["47","62","32","35"],"ans":3,"time":38,"sol":["Runs so far = 32 × 9 = 288","After the 10th: 288 + 62 = 350","New average = 350 ÷ 10 = **35**"],"short":"Total runs ÷ innings: the 62 is shared over 10 innings.","trap":"Averaging the old average with the new score.","why":["Averaged 32 and 62","Gave the latest score","Assumed the average does not change",null],"calc":"(32*9+62)/10"},
  {"id":"averages-04","sec":"quant","topic":"averages","pattern":"new-member-replaces-one","d":"Medium","q":"The average age of 8 men goes up by 3 years when a man aged 40 is replaced by a new man. What is the age of the new man?","opts":["43","48","64","52"],"ans":2,"time":60,"sol":["Total age rises by 8 × 3 = 24","New man is 24 years older than the man he replaced","Age = 40 + 24 = **64**"],"short":"Change in total = change in average × number of people.","trap":"Adding only the 3 years to the old man's age.","why":["Added only the rise in average (3)","Added the group size (8)",null,"Added 3 × 4, using half the group"],"calc":"40+8*3"},
  {"id":"averages-06","sec":"quant","topic":"averages","pattern":"weighted-average","d":"Medium","q":"A class has 24 boys with an average mark of 70 and 16 girls with an average mark of 80. What is the average mark of the whole class?","opts":["75","76","74","80"],"ans":2,"time":60,"sol":["Total = 24 × 70 + 16 × 80 = 1,680 + 1,280 = 2,960","Average = 2,960 ÷ 40 = **74**"],"short":"More boys, so the average sits closer to 70: 70 + 10 × 16/40.","trap":"Taking (70 + 80) ÷ 2 without weighting.","why":["Took the simple average of 70 and 80","Swapped the weights (24 girls, 16 boys)",null,"Gave the girls' average"],"calc":"(24*70+16*80)/40"},
  {"id":"averages-08","sec":"quant","topic":"averages","pattern":"correcting-a-wrongly-copied-value","d":"Hard","q":"The average of 50 numbers was calculated as 38. It was later found that 48 had been read as 84 and 53 had been read as 35. What is the correct average?","opts":["37.28","37.64","38.36","38"],"ans":1,"time":95,"sol":["Wrong total = 38 × 50 = 1,900","Correction = −84 + 48 − 35 + 53 = −18","Correct total = 1,882, average = **37.64**"],"short":"Net correction −18 spread over 50 numbers is −0.36.","trap":"Adding a correction when the number was over-read, or vice versa.","why":["Corrected only the first error",null,"Applied both corrections in the wrong direction","Assumed the two errors cancel"],"calc":"(50*38-84+48-35+53)/50"},
  {"id":"ages-01","sec":"quant","topic":"ages","pattern":"sum-and-ratio","d":"Easy","q":"The sum of the ages of a father and his son is 60 years and their ages are in the ratio 7 : 3. How old is the son?","opts":["42 years","18 years","20 years","30 years"],"ans":1,"time":38,"sol":["Total parts = 7 + 3 = 10, so 1 part = 6 years","Son = 3 × 6 = **18 years**"],"short":"60 ÷ 10 = 6 per part; the smaller ratio number is the son.","trap":"Picking the wrong member's age.","why":["Gave the father's age",null,"Divided 60 by 3","Halved the sum"],"calc":"60*3/10"},
  {"id":"ages-02","sec":"quant","topic":"ages","pattern":"ratio-now-then","d":"Easy","q":"The ages of Asha and Bina are in the ratio 3 : 5. If Asha is 21 years old, how old is Bina?","opts":["12.6 years","35 years","14 years","105 years"],"ans":1,"time":38,"sol":["3 parts = 21, so 1 part = 7","Bina = 5 × 7 = **35 years**"],"short":"One part = 21 ÷ 3 = 7.","trap":"Multiplying by the ratio number instead of using one part.","why":["Used 3 : 5 the wrong way (21 × 3/5)",null,"Gave the age difference","Multiplied 21 by 5"],"calc":"21/3*5"},
  {"id":"ages-03","sec":"quant","topic":"ages","pattern":"n-years-ago-it-was","d":"Easy","q":"Six years ago, Neha's age was one-third of her present age. How old is she now?","opts":["12 years","9 years","6 years","3 years"],"ans":1,"time":38,"sol":["Let her age now be x: x − 6 = x/3","3x − 18 = x, so 2x = 18","x = **9 years**"],"short":"The 6 years are 2/3 of her age now (x − x/3), so x = 9.","trap":"Stopping at her age six years ago (3).","why":["Solved x − 6 = x/2",null,"Gave the number of years","Gave her age six years ago"],"calc":"6*3/2"},
  {"id":"ages-04","sec":"quant","topic":"ages","pattern":"ratio-now-then","d":"Medium","q":"The present ages of A and B are in the ratio 4 : 5. Eight years from now the ratio will be 5 : 6. What is A's present age?","opts":["40 years","32 years","48 years","36 years"],"ans":1,"time":60,"sol":["Present ages 4k and 5k: (4k + 8) ÷ (5k + 8) = 5/6","24k + 48 = 25k + 40, so k = 8","A = 4 × 8 = **32 years**"],"short":"Cross-multiply, solve for k, then multiply back.","trap":"Giving the age after 8 years instead of the present age.","why":["Gave A's age after 8 years (also B's present age)",null,"Gave B's age after 8 years","Averaged the two present ages"],"calc":"4*8"},
  {"id":"ages-07","sec":"quant","topic":"ages","pattern":"parent-and-children","d":"Medium","q":"The average age of a family of five, a father, a mother and three children, is 22 years. The average age of the three children is 10 years. If the father is 4 years older than the mother, how old is the father?","opts":["38 years","40 years","42 years","44 years"],"ans":2,"time":60,"sol":["Family total = 22 × 5 = 110; children's total = 30","Parents' total = 80, so father + mother = 80 with a gap of 4","Father = (80 + 4) ÷ 2 = **42 years**"],"short":"Parents sum 80; larger = (sum + gap) ÷ 2.","trap":"Giving the parents' average (40) instead of splitting it with the 4-year gap.","why":["Gave the mother's age","Gave the average age of the parents",null,"Added 4 to the average age of the parents"],"calc":"(22*5-30+4)/2"},
  {"id":"time-work-01","sec":"quant","topic":"time-work","pattern":"days-efficiency","d":"Easy","q":"A can finish a job in 10 days and B can finish it in 15 days. In how many days will they finish it working together?","opts":["12.5 days","6 days","25 days","5 days"],"ans":1,"time":38,"sol":["Rates: 1/10 + 1/15 = 5/30 = 1/6 per day","Time = **6 days**"],"short":"Product ÷ sum = 150 ÷ 25 = 6.","trap":"Averaging the days; together they must be faster than either alone.","why":["Took the average of 10 and 15",null,"Added the two times","Subtracted the two times"],"calc":"1/(1/10+1/15)"},
  {"id":"time-work-02","sec":"quant","topic":"time-work","pattern":"lcm-method","d":"Easy","q":"A, B and C can do a work alone in 20, 30 and 60 days. How many days will they take working together?","opts":["12 days","36.7 days","10 days","30 days"],"ans":2,"time":38,"sol":["Take total work = LCM = 60 units","Per day: A 3, B 2, C 1, together 6 units","Days = 60 ÷ 6 = **10**"],"short":"LCM work: 60 units, 3 + 2 + 1 = 6 per day.","trap":"Averaging the number of days.","why":["Left out C","Took the average of 20, 30 and 60",null,"Took the middle value"],"calc":"60/(3+2+1)"},
  {"id":"time-work-04","sec":"quant","topic":"time-work","pattern":"together-then-one-leaves","d":"Medium","q":"A alone can do a job in 24 days and B alone in 36 days. They work together for 8 days and then A leaves. How many more days will B need to finish the job?","opts":["24 days","16 days","28 days","6.4 days"],"ans":1,"time":60,"sol":["Total = LCM 72 units; A does 3, B does 2 per day","Work in 8 days = 8 × 5 = 40; left = 32","B alone: 32 ÷ 2 = **16 days**"],"short":"72 units; 40 done together, 32 left at 2 per day.","trap":"Answering with total elapsed time or forgetting A's share of the first 8 days.","why":["Gave the total time instead of the extra days",null,"Counted only B's work in the first 8 days","Let A keep working with B"],"calc":"(72-8*(3+2))/2"},
  {"id":"time-work-05","sec":"quant","topic":"time-work","pattern":"alternate-days","d":"Medium","q":"A can do a job in 10 days and B in 15 days. They work on alternate days, starting with A. In how many days will the job be finished?","opts":["6 days","12 days","12.5 days","13 days"],"ans":1,"time":60,"sol":["Total work = 30 units; A does 3 and B does 2 per day","One 2-day cycle = 5 units; 6 cycles = 30 units","Time = 6 × 2 = **12 days**"],"short":"Two-day cycle of 5 units: 30 ÷ 5 × 2 = 12.","trap":"Using the together rate, which would make the job much faster.","why":["Worked out the time for working together",null,"Took the average of 10 and 15","Added one extra day for the last cycle"],"calc":"30/(3+2)*2"},
  {"id":"time-work-06","sec":"quant","topic":"time-work","pattern":"work-and-wages","d":"Medium","q":"A, B and C together finish a job and are paid ₹4,500. A alone would take 6 days, B 8 days and C 12 days. If wages are shared in proportion to work done, how much does C get?","opts":["₹1,500","₹2,000","₹1,000","₹750"],"ans":2,"time":60,"sol":["Daily work ratio = 1/6 : 1/8 : 1/12 = 4 : 3 : 2","C's share = 2/9 × 4,500 = **₹1,000**"],"short":"Wages follow the work done, i.e. the efficiency ratio 4 : 3 : 2.","trap":"Splitting equally or using the ratio of days (6 : 8 : 12) directly.","why":["Split the pay equally","Gave A's share",null,"Halved the equal share"],"calc":"4500*(1/12)/(1/6+1/8+1/12)"},
  {"id":"pipes-01","sec":"quant","topic":"pipes","pattern":"fill-empty-together","d":"Easy","q":"Pipe A can fill a tank in 10 hours and pipe B can fill it in 15 hours. How long will they take to fill the tank together?","opts":["6 hours","12.5 hours","25 hours","5 hours"],"ans":0,"time":38,"sol":["Rates: 1/10 + 1/15 = 1/6 of the tank per hour","Time = **6 hours**"],"short":"Product ÷ sum: 150 ÷ 25 = 6.","trap":"Averaging the times; two filling pipes must be faster than either.","why":[null,"Took the average of 10 and 15","Added the two times","Subtracted the two times"],"calc":"1/(1/10+1/15)"},
  {"id":"pipes-02","sec":"quant","topic":"pipes","pattern":"fill-empty-together","d":"Easy","q":"A tap fills a tank in 6 hours and an outlet pipe empties it in 10 hours. If both are opened together on an empty tank, how long does it take to fill?","opts":["3.75 hours","15 hours","4 hours","16 hours"],"ans":1,"time":38,"sol":["Net rate = 1/6 − 1/10 = 1/15 per hour","Time = **15 hours**"],"short":"Subtract the emptying rate: 60 ÷ (10 − 6) = 15 on LCM 30.","trap":"Treating the outlet as another inlet.","why":["Added the two rates (as if both filled)",null,"Subtracted the times (10 − 6)","Added the two times"],"calc":"1/(1/6-1/10)"},
  {"id":"pipes-03","sec":"quant","topic":"pipes","pattern":"a-leak","d":"Easy","q":"A pipe can fill a tank in 4 hours, but because of a leak it takes 5 hours. In how many hours would the leak alone empty the full tank?","opts":["1 hour","9 hours","20 hours","4.5 hours"],"ans":2,"time":38,"sol":["Leak rate = 1/4 − 1/5 = 1/20 per hour","Leak empties the tank in **20 hours**"],"short":"Product ÷ difference: 4 × 5 ÷ 1.","trap":"Subtracting the times rather than the rates.","why":["Subtracted the two times","Added the two times",null,"Took the average of 4 and 5"],"calc":"1/(1/4-1/5)"},
  {"id":"pipes-05","sec":"quant","topic":"pipes","pattern":"closed-after-some-time","d":"Medium","q":"Pipes A and B can fill a tank in 15 and 20 minutes. Both are opened together, but B is closed after 6 minutes. How long does the tank take to fill in all?","opts":["4.5 minutes","8.6 minutes","10.5 minutes","12 minutes"],"ans":2,"time":60,"sol":["Take 60 units: A 4 per minute, B 3 per minute","First 6 minutes: 6 × 7 = 42; left 18","A alone: 18 ÷ 4 = 4.5 minutes, total = **10.5 minutes**"],"short":"42 done together; the rest at A's rate; add the 6 minutes back.","trap":"Forgetting to add the first 6 minutes.","why":["Gave only the time after B was closed","Found the time with both open throughout",null,"Closed A instead of B"],"calc":"6+(60-6*7)/4"},
  {"id":"pipes-06","sec":"quant","topic":"pipes","pattern":"tank-capacity-from-rates","d":"Medium","q":"An inlet pipe pours in 12 litres a minute and an outlet drains 8 litres a minute. With both open, an empty tank is filled in 45 minutes. What is the capacity of the tank?","opts":["540 L","360 L","900 L","180 L"],"ans":3,"time":60,"sol":["Net rate = 12 − 8 = 4 L per minute","Capacity = 4 × 45 = **180 L**"],"short":"Net rate × time.","trap":"Using the inlet rate alone, forgetting the drain.","why":["Used the inlet rate alone (12 × 45)","Used the outlet rate alone (8 × 45)","Added the two rates (20 × 45)",null],"calc":"(12-8)*45"},
  {"id":"tsd-01","sec":"quant","topic":"tsd","pattern":"basics-and-km-h-m","d":"Easy","q":"Convert a speed of 72 km/h into metres per second.","opts":["12 m/s","20 m/s","40 m/s","259.2 m/s"],"ans":1,"time":38,"sol":["km/h to m/s: multiply by 5/18","72 × 5/18 = **20 m/s**"],"short":"÷ 3.6 for km/h to m/s; × 3.6 for the reverse.","trap":"Multiplying when you should divide by 3.6.","why":["Divided by 6",null,"Multiplied by 5/9","Multiplied by 3.6"],"calc":"72*5/18"},
  {"id":"tsd-02","sec":"quant","topic":"tsd","pattern":"average-speed","d":"Easy","q":"A car goes from town A to town B at 60 km/h and returns along the same road at 40 km/h. What is its average speed for the round trip?","opts":["50 km/h","100 km/h","48 km/h","20 km/h"],"ans":2,"time":38,"sol":["Equal distances: average = 2xy ÷ (x + y)","2 × 60 × 40 ÷ 100 = **48 km/h**"],"short":"Equal distances use the harmonic mean, never the simple mean.","trap":"(60 + 40) ÷ 2 = 50 is wrong, since more time is spent at 40.","why":["Took the simple average","Added the two speeds",null,"Subtracted the two speeds"],"calc":"2*60*40/(60+40)"},
  {"id":"tsd-03","sec":"quant","topic":"tsd","pattern":"trains-pole-man","d":"Easy","q":"A 150 m long train runs at 54 km/h. How long does it take to cross a pole?","opts":["2.8 s","10 s","15 s","27 s"],"ans":1,"time":38,"sol":["54 km/h = 54 × 5/18 = 15 m/s","Time = 150 ÷ 15 = **10 s**"],"short":"Convert first (54 → 15 m/s); a pole means distance = train length.","trap":"Dividing metres by km/h.","why":["Divided the length by 54 without converting",null,"Gave the speed in m/s","Halved 54"],"calc":"150/(54*5/18)"},
  {"id":"tsd-06","sec":"quant","topic":"tsd","pattern":"trains-platform-bridge","d":"Medium","q":"A 240 m long train passes a 360 m long platform in 30 seconds. How long does it take to pass a pole?","opts":["12 s","18 s","30 s","8 s"],"ans":0,"time":60,"sol":["Distance for the platform = 240 + 360 = 600 m","Speed = 600 ÷ 30 = 20 m/s","Pole: 240 ÷ 20 = **12 s**"],"short":"Platform: train + platform length; pole: train length only.","trap":"Using only the train length for the speed.","why":[null,"Divided the platform length by the speed","Gave the time for the platform","Divided 240 by 30"],"calc":"240/((240+360)/30)"},
  {"id":"tsd-07","sec":"quant","topic":"tsd","pattern":"boats-and-streams","d":"Medium","q":"A boat's speed in still water is 12 km/h and the stream flows at 3 km/h. It goes 36 km downstream and comes back to the starting point. How many hours does the round trip take?","opts":["4.8 h","6 h","6.4 h","8 h"],"ans":2,"time":60,"sol":["Downstream speed = 15 km/h, upstream = 9 km/h","Time = 36/15 + 36/9 = 2.4 + 4","Total = **6.4 h**"],"short":"Downstream = b + s, upstream = b − s; add the two times.","trap":"Using the still-water speed for the whole trip.","why":["Used the downstream speed for both ways","Ignored the stream",null,"Used the upstream speed for both ways"],"calc":"36/15+36/9"},
  {"id":"pnc-01","sec":"quant","topic":"pnc","pattern":"counting-principle","d":"Easy","q":"A student has **4** shirts, **3** trousers and **2** pairs of shoes. How many different outfits (one shirt, one trouser, one pair of shoes) can she make?","opts":["9","12","24","6"],"ans":2,"time":35,"sol":["Independent choices multiply","4 × 3 × 2 = **24**"],"short":"Choices at each stage multiply: 4 × 3 × 2.","trap":"Adding the numbers of choices.","why":["Added 4 + 3 + 2 instead of multiplying","Ignored the shoes",null,"Ignored the shirts"],"calc":"4*3*2"},
  {"id":"pnc-03","sec":"quant","topic":"pnc","pattern":"words-from-letters-with-repeats","d":"Medium","q":"How many distinct arrangements can be made from all the letters of the word **BANANA**?","opts":["720","120","360","60"],"ans":3,"time":55,"sol":["BANANA has 6 letters: A three times, N twice, B once","6! ÷ (3! × 2!) = 720 ÷ 12 = **60**"],"short":"Total! ÷ (repeat counts)!.","trap":"Dividing by only one of the repeated letters.","why":["Treated all 6 letters as different (6!)","Divided by 3! only, ignoring the repeated N's","Divided by 2! only, ignoring the three A's",null],"calc":"720/(6*2)"},
  {"id":"pnc-05","sec":"quant","topic":"pnc","pattern":"selection-ncr-at-least-at","d":"Easy","q":"In how many ways can **3** books be chosen from **8** different books on a shelf?","opts":["336","56","24","512"],"ans":1,"time":40,"sol":["Order does not matter, so use combinations","8C3 = (8 × 7 × 6) ÷ (3 × 2 × 1) = **56**"],"short":"nCr: multiply r numbers down from n, divide by r!.","trap":"Using 8P3 when order is irrelevant.","why":["Used permutations (order counted)",null,"Took 8 × 3","Took 8³"],"calc":"8*7*6/6"},
  {"id":"pnc-07","sec":"quant","topic":"pnc","pattern":"committees-with-conditions","d":"Hard","q":"A team of **4** is chosen from **5 men and 4 women** so that it has **at least 2 women**. In how many ways is this possible?","opts":["121","86","126","81"],"ans":3,"time":100,"sol":["Total teams = 9C4 = 126","0 women: 5C4 = 5; 1 woman: 4 × 5C3 = 40","At least 2 women = 126 − 5 − 40 = **81**"],"short":"Complement: total − (0 women) − (1 woman).","trap":"Removing only one of the two unwanted cases.","why":["Subtracted only the 'no woman' case","Subtracted only the 'one woman' case","Counted all 4-member teams (9C4)",null],"calc":"126-5-40"},
  {"id":"pnc-10","sec":"quant","topic":"pnc","pattern":"distribution","d":"Hard","q":"In how many ways can **10 identical** sweets be distributed among **4 children** so that every child gets **at least one**?","opts":["286","210","84","120"],"ans":2,"time":90,"sol":["Give each child 1 first; 6 sweets remain","Distribute 6 identical sweets among 4 children freely: (6 + 3)C3 = 9C3 = **84**"],"short":"Positive solutions of x₁ + … + x_k = n number (n − 1)C(k − 1).","trap":"Using the formula for 'zero allowed'.","why":["Allowed zero sweets (13C3)","Used 10C4",null,"Used 10C3"],"calc":"84"},
  {"id":"probability-01","sec":"quant","topic":"probability","pattern":"coins","d":"Easy","q":"Three fair coins are tossed together. What is the probability of getting **exactly two heads**?","opts":["3/8","1/4","1/2","1/8"],"ans":0,"time":40,"sol":["Sample space = 2³ = 8","Exactly two heads: HHT, HTH, THH = 3 outcomes","P = **3/8**"],"short":"3C2 ÷ 2³.","trap":"Counting HHT as the only way.","why":[null,"Counted 2 of the 8 outcomes","Counted 'at least two heads' (4 of 8)","Counted a single outcome HHT"],"calc":"3/8"},
  {"id":"probability-02","sec":"quant","topic":"probability","pattern":"dice","d":"Easy","q":"Two fair dice are thrown. What is the probability that the **sum is 8**?","opts":["5/36","1/6","1/9","1/8"],"ans":0,"time":40,"sol":["Total outcomes = 36","Sum 8: (2,6), (3,5), (4,4), (5,3), (6,2) = 5 ways","P = **5/36**"],"short":"List the pairs; the (4,4) pair counts only once.","trap":"Mixing up the counts for sums 7 and 8.","why":[null,"Used the 6 ways of getting a sum of 7","Counted 4 ways instead of 5","Took 1 ÷ 8"],"calc":"5/36"},
  {"id":"probability-04","sec":"quant","topic":"probability","pattern":"cards","d":"Medium","q":"One card is drawn from a well-shuffled pack of 52. What is the probability that it is a **king or a heart**?","opts":["4/13","17/52","1/2","5/13"],"ans":0,"time":50,"sol":["Kings = 4, hearts = 13, king of hearts is in both","Favourable = 4 + 13 − 1 = 16","P = 16/52 = **4/13**"],"short":"P(A or B) = P(A) + P(B) − P(A and B).","trap":"Double-counting the king of hearts.","why":[null,"Added 4 + 13 and forgot the king of hearts is counted twice","Counted all red cards","Added 4/13 + 1/13 wrongly"],"calc":"16/52"},
  {"id":"probability-06","sec":"quant","topic":"probability","pattern":"balls-from-bags-with-without","d":"Medium","q":"A bag has **5 red, 4 blue and 3 green** balls. Two balls are drawn at random **without replacement**. What is the probability that **both are red**?","opts":["25/144","5/33","5/12","10/33"],"ans":1,"time":65,"sol":["Total pairs = 12C2 = 66; red pairs = 5C2 = 10","P = 10/66 = **5/33**"],"short":"(5/12) × (4/11) = 20/132 = 5/33.","trap":"Not reducing the second denominator to 11.","why":["Used replacement: (5/12)²",null,"Gave the chance for the first ball only","Counted ordered pairs of reds over unordered pairs"],"calc":"10/66"},
  {"id":"probability-08","sec":"quant","topic":"probability","pattern":"at-least-one","d":"Hard","q":"A fair die is thrown **4 times**. What is the probability of getting **at least one six**?","opts":["671/1296","625/1296","2/3","1/1296"],"ans":0,"time":90,"sol":["P(no six) = (5/6)⁴ = 625/1296","P(at least one six) = 1 − 625/1296 = **671/1296**"],"short":"At least one = 1 − P(none).","trap":"Adding 1/6 four times, which over-counts overlaps.","why":[null,"Gave the probability of no six at all","Added 4 × 1/6","Gave the probability of four sixes"],"calc":"671/1296"},
  {"id":"mensuration-2d-01","sec":"quant","topic":"mensuration-2d","pattern":"rectangles-and-squares","d":"Easy","q":"A rectangular park measures **24 m by 18 m**. What is the length of the diagonal path across it?","opts":["42 m","30 m","432 m","6 m"],"ans":1,"time":40,"sol":["Diagonal = √(24² + 18²) = √(576 + 324)","= √900 = **30 m**"],"short":"Scale the 3-4-5 triple: 6 × (4, 3, 5).","trap":"Adding the sides instead of using Pythagoras.","why":["Added the two sides",null,"Gave the area","Subtracted the sides"],"calc":"Math.hypot(24,18)"},
  {"id":"mensuration-2d-03","sec":"quant","topic":"mensuration-2d","pattern":"triangles","d":"Easy","q":"What is the area of a triangle with sides **13 cm, 14 cm and 15 cm**?","opts":["91 cm²","168 cm²","84 cm²","42 cm²"],"ans":2,"time":50,"sol":["s = (13 + 14 + 15) ÷ 2 = 21","Area = √(21 × 8 × 7 × 6) = √7056 = **84 cm²**"],"short":"13-14-15: height on the 14 side is 12, so ½ × 14 × 12.","trap":"Treating two sides as base and height.","why":["Took ½ × 13 × 14, as if the sides were base and height","Forgot the ½ in base × height (14 × 12)",null,"Gave the semi-perimeter"],"calc":"Math.sqrt(21*8*7*6)"},
  {"id":"mensuration-2d-05","sec":"quant","topic":"mensuration-2d","pattern":"circles-sectors-rings","d":"Easy","q":"The circumference of a circular plate is **88 cm**. Find its area. (Take π = 22/7.)","opts":["616 cm²","1,232 cm²","308 cm²","196 cm²"],"ans":0,"time":50,"sol":["2πr = 88, so r = 88 × 7 ÷ 44 = 14 cm","Area = (22/7) × 14 × 14 = **616 cm²**"],"short":"Circumference 88 gives radius 14.","trap":"Using the circumference as if it were the diameter.","why":[null,"Used 2πr² (twice the area)","Halved the area","Gave r²"],"calc":"22/7*14*14"},
  {"id":"mensuration-2d-08","sec":"quant","topic":"mensuration-2d","pattern":"pct-change-in-area","d":"Hard","q":"The **diagonal** of a square is increased by **20%**. By what percent does its **area** increase?","opts":["20%","40%","44%","144%"],"ans":2,"time":75,"sol":["Area of a square = d²/2, so area ∝ d²","New area = 1.2² = 1.44 times the old one","Increase = **44%**"],"short":"Any linear scale of x raises area by x²: 1.2² = 1.44.","trap":"Forgetting that area scales as the square.","why":["Used the same percent as the diagonal","Doubled the 20% rise",null,"Gave the new area as a percent of the old"],"calc":"(1.2*1.2-1)*100"},
  {"id":"mensuration-2d-09","sec":"quant","topic":"mensuration-2d","pattern":"trapezium-rhombus-parallelogram","d":"Hard","q":"A trapezium has area **180 cm²** and height **10 cm**. Its two parallel sides differ by **6 cm**. How long is the **longer** parallel side?","opts":["15 cm","21 cm","18 cm","36 cm"],"ans":1,"time":90,"sol":["½ × (a + b) × 10 = 180, so a + b = 36","a − b = 6, so a = (36 + 6) ÷ 2 = **21 cm**"],"short":"Sum from the area, difference from the question.","trap":"Stopping at a + b = 36.","why":["Gave the shorter parallel side",null,"Gave the average of the parallel sides","Gave the sum of the parallel sides"],"calc":"21"},
  {"id":"mensuration-3d-01","sec":"quant","topic":"mensuration-3d","pattern":"cube-and-cuboid","d":"Easy","q":"The total surface area of a cube is **150 cm²**. What is its volume?","opts":["25 cm³","5 cm³","125 cm³","900 cm³"],"ans":2,"time":40,"sol":["6a² = 150, so a² = 25 and a = 5 cm","Volume = 5³ = **125 cm³**"],"short":"TSA ÷ 6 = face area; its root is the edge.","trap":"Stopping at the edge.","why":["Gave the area of one face","Gave the edge",null,"Multiplied the surface area by 6"],"calc":"125"},
  {"id":"mensuration-3d-03","sec":"quant","topic":"mensuration-3d","pattern":"cylinder","d":"Easy","q":"Find the volume of a cylinder of radius **7 cm** and height **10 cm**. (Take π = 22/7.)","opts":["440 cm³","1,540 cm³","3,080 cm³","154 cm³"],"ans":1,"time":40,"sol":["Volume = πr²h = (22/7) × 49 × 10","= 154 × 10 = **1540 cm³**"],"short":"(22/7) × 49 = 154, then × height.","trap":"Using the curved-surface formula.","why":["Gave the curved surface area",null,"Used 2πr²h","Gave the base area only"],"calc":"22/7*49*10"},
  {"id":"mensuration-3d-04","sec":"quant","topic":"mensuration-3d","pattern":"cone","d":"Medium","q":"A cone has base radius **7 cm** and height **24 cm**. Find its **total surface area**. (Take π = 22/7.)","opts":["704 cm²","550 cm²","154 cm²","1,408 cm²"],"ans":0,"time":70,"sol":["Slant height l = √(7² + 24²) = 25 cm","Curved = πrl = (22/7) × 7 × 25 = 550","Base = πr² = 154, so total = **704 cm²**"],"short":"7-24-25 triple; total = πr(l + r).","trap":"Leaving out the base circle.","why":[null,"Gave the curved surface only","Gave the base area only","Doubled the total"],"calc":"22/7*7*(25+7)"},
  {"id":"mensuration-3d-06","sec":"quant","topic":"mensuration-3d","pattern":"melting-and-recasting","d":"Hard","q":"A solid metal sphere of radius **9 cm** is melted and recast into small cones, each with base radius **3 cm** and height **9 cm**. How many cones are made?","opts":["12","36","27","108"],"ans":1,"time":95,"sol":["Sphere: (4/3)π × 729 = 972π","Cone: (1/3)π × 9 × 9 = 27π","Number = 972 ÷ 27 = **36**"],"short":"Volume is conserved: divide the volumes, π cancels.","trap":"Dropping a fraction in one of the volume formulas.","why":["Forgot the ⅓ in the cone's volume",null,"Forgot the 4/3 in the sphere's volume","Used 4πr³ for the sphere"],"calc":"(4/3*729)/(1/3*9*9)"},
  {"id":"mensuration-3d-08","sec":"quant","topic":"mensuration-3d","pattern":"cost-of-painting-tiling","d":"Medium","q":"A room is **8 m long, 6 m wide and 3 m high**. Find the cost of painting its **four walls** at **₹25 per m²**. (Ignore doors and windows.)","opts":["₹3,300","₹4,500","₹2,100","₹1,200"],"ans":2,"time":60,"sol":["Four walls = 2(l + b)h = 2 × 14 × 3 = 84 m²","Cost = 84 × 25 = **₹2,100**"],"short":"Walls = perimeter of the floor × height.","trap":"Adding the floor or ceiling.","why":["Included the floor as well","Painted all six faces",null,"Painted only the floor"],"calc":"84*25"},
  {"id":"geometry-01","sec":"quant","topic":"geometry","pattern":"angles-and-parallel-lines","d":"Easy","q":"Two parallel lines are cut by a transversal. One of the **co-interior (same-side interior)** angles is **115°**. What is the other?","opts":["65°","115°","25°","295°"],"ans":0,"time":35,"sol":["Co-interior angles are supplementary","180° − 115° = **65°**"],"short":"Co-interior add to 180°; alternate and corresponding are equal.","trap":"Mixing up co-interior with alternate angles.","why":[null,"Assumed co-interior angles are equal","Took 90° − 65°","Took 360° − 65°"],"calc":"180-115"},
  {"id":"geometry-02","sec":"quant","topic":"geometry","pattern":"triangle-properties-and-pythagorean-triplets","d":"Medium","q":"A right-angled triangle has hypotenuse **26 cm** and one leg **10 cm**. What is its area?","opts":["240 cm²","120 cm²","130 cm²","60 cm²"],"ans":1,"time":60,"sol":["Other leg = √(26² − 10²) = √576 = 24 cm (5-12-13 doubled)","Area = ½ × 10 × 24 = **120 cm²**"],"short":"10-24-26 is twice 5-12-13.","trap":"Using the hypotenuse as a base.","why":["Forgot the ½",null,"Took ½ × hypotenuse × leg","Gave the perimeter, 10 + 24 + 26"],"calc":"0.5*10*24"},
  {"id":"geometry-04","sec":"quant","topic":"geometry","pattern":"circle-theorems","d":"Medium","q":"A point P is **17 cm** from the centre of a circle of radius **8 cm**. What is the length of the tangent from P to the circle?","opts":["9 cm","25 cm","18.79 cm","15 cm"],"ans":3,"time":60,"sol":["The tangent is perpendicular to the radius at the point of contact","Length = √(17² − 8²) = √225 = **15 cm**"],"short":"8-15-17 triple.","trap":"Adding the squares instead of subtracting.","why":["Took 17 − 8","Took 17 + 8","Used √(17² + 8²)",null],"calc":"Math.sqrt(289-64)"},
  {"id":"geometry-05","sec":"quant","topic":"geometry","pattern":"polygons","d":"Easy","q":"Each interior angle of a regular polygon is **140°**. How many sides does it have?","opts":["8","10","12","9"],"ans":3,"time":45,"sol":["Exterior angle = 180° − 140° = 40°","Sides = 360° ÷ 40° = **9**"],"short":"Exterior angles of any polygon add to 360°.","trap":"Dividing 360 by the interior angle.","why":["Off by one: 360 ÷ 45","Used an exterior angle of 36°","Used an exterior angle of 30°",null],"calc":"360/40"},
  {"id":"geometry-07","sec":"quant","topic":"geometry","pattern":"coordinate-basics","d":"Easy","q":"Find the distance between the points **(−2, 3)** and **(4, −5)**.","opts":["14","100","10","48"],"ans":2,"time":45,"sol":["Δx = 6, Δy = −8","Distance = √(36 + 64) = **10**"],"short":"A 6-8-10 triple.","trap":"Taking the gaps with the wrong sign: −2 − 4 is 6, not 2.","why":["Added the horizontal and vertical gaps (6 + 8)","Forgot the square root",null,"Multiplied 6 × 8"],"calc":"Math.hypot(6,8)"},
  {"id":"algebra-01","sec":"quant","topic":"algebra","pattern":"linear-equations","d":"Easy","q":"Solve for x: **5x − 8 = 3x + 10**.","opts":["9","1","−9","18"],"ans":0,"time":35,"sol":["Move terms: 5x − 3x = 10 + 8","2x = 18, so x = **9**"],"short":"Collect x on one side, numbers on the other.","trap":"Subtracting the 8 instead of adding it.","why":[null,"Divided (10 − 8) by 2","Sign error when moving terms","Stopped at 2x = 18"],"calc":"9"},
  {"id":"algebra-03","sec":"quant","topic":"algebra","pattern":"word-problems-equations","d":"Medium","q":"A father is **3 times** as old as his son. After **10 years** he will be **twice** as old as his son. What is the father's present age?","opts":["40 years","10 years","20 years","30 years"],"ans":3,"time":55,"sol":["Son = s, father = 3s","3s + 10 = 2(s + 10), so s = 10","Father = 3 × 10 = **30 years**"],"short":"Test: 30 and 10 now, 40 and 20 later.","trap":"Answering with the son's age.","why":["Gave the father's age after 10 years","Gave the son's age","Gave the son's age after 10 years",null],"calc":"30"},
  {"id":"algebra-05","sec":"quant","topic":"algebra","pattern":"quadratics","d":"Medium","q":"If α and β are the roots of **x² − 5x + 3 = 0**, find **α² + β²**.","opts":["25","31","22","19"],"ans":3,"time":60,"sol":["α + β = 5 and αβ = 3","α² + β² = (α + β)² − 2αβ = 25 − 6 = **19**"],"short":"Never solve for the roots: use sum and product.","trap":"Using − αβ instead of − 2αβ.","why":["Squared the sum and stopped","Added 2αβ instead of subtracting","Subtracted αβ instead of 2αβ",null],"calc":"25-6"},
  {"id":"algebra-07","sec":"quant","topic":"algebra","pattern":"inequalities-and-modulus","d":"Medium","q":"How many **integers** satisfy **|2x − 3| < 7**?","opts":["8","5","6","4"],"ans":2,"time":65,"sol":["−7 < 2x − 3 < 7, so −4 < 2x < 10","−2 < x < 5: integers −1, 0, 1, 2, 3, 4 = **6**"],"short":"Strict inequality drops both end values.","trap":"Including −2 and 5.","why":["Treated < as ≤","Left out zero",null,"Counted only the positive integers"],"calc":"6"},
  {"id":"algebra-09","sec":"quant","topic":"algebra","pattern":"identities","d":"Hard","q":"If **x + 1/x = 3**, find **x³ + 1/x³**.","opts":["18","27","24","36"],"ans":0,"time":80,"sol":["(x + 1/x)³ = x³ + 1/x³ + 3(x + 1/x)","27 = x³ + 1/x³ + 9","x³ + 1/x³ = **18**"],"short":"a³ + b³ = (a + b)³ − 3ab(a + b), with ab = 1.","trap":"Subtracting 3 instead of 3 × 3.","why":[null,"Cubed the sum and stopped","Subtracted 3 instead of 3 × 3","Added 9 instead of subtracting"],"calc":"27-9"},
  {"id":"progressions-01","sec":"quant","topic":"progressions","pattern":"ap-nth-term-and-sum","d":"Easy","q":"Find the **20th term** of the AP **5, 9, 13, …**","opts":["85","77","81","76"],"ans":2,"time":40,"sol":["a = 5, d = 4","aₙ = a + (n − 1)d = 5 + 19 × 4 = **81**"],"short":"There are 19 jumps between 20 terms.","trap":"Using n instead of n − 1.","why":["Used a + nd (20 steps)","Used 18 steps",null,"Used 19 × 4 without adding a"],"calc":"5+19*4"},
  {"id":"progressions-03","sec":"quant","topic":"progressions","pattern":"ap-nth-term-and-sum","d":"Medium","q":"What is the sum of all multiples of **7** between **1 and 200**?","opts":["3,045","5,684","2,646","2,842"],"ans":3,"time":65,"sol":["Multiples: 7, 14, …, 196 — that is 28 terms (196 ÷ 7)","S = 28/2 × (7 + 196) = 14 × 203 = **2842**"],"short":"7 × (1 + 2 + … + 28) = 7 × 406.","trap":"Rounding 200 ÷ 7 up to 29.","why":["Included 203, beyond 200","Forgot the ½","Counted only 27 terms",null],"calc":"14*203"},
  {"id":"progressions-05","sec":"quant","topic":"progressions","pattern":"gp-nth-term-and-sum","d":"Easy","q":"Find the sum of the first **6 terms** of the GP **2, 6, 18, …**","opts":["486","1,456","729","728"],"ans":3,"time":50,"sol":["a = 2, r = 3","S = a(rⁿ − 1)/(r − 1) = 2(729 − 1)/2 = **728**"],"short":"Here 2/(3 − 1) = 1, so S = 3⁶ − 1.","trap":"Reporting the last term instead of the sum.","why":["Gave the 6th term","Forgot to divide by r − 1","Used 3⁶ without subtracting 1",null],"calc":"2*(729-1)/2"},
  {"id":"progressions-08","sec":"quant","topic":"progressions","pattern":"am-gm-hm","d":"Medium","q":"The arithmetic mean of two positive numbers is **10** and their geometric mean is **8**. What is their **harmonic mean**?","opts":["6.4","9","6","12.5"],"ans":0,"time":70,"sol":["For two numbers, GM² = AM × HM","HM = 64 ÷ 10 = **6.4**"],"short":"GM² = AM × HM (two numbers only).","trap":"Averaging the other two means.","why":[null,"Averaged the AM and GM","Used 2·GM − AM","Inverted the relation: AM²/GM"],"calc":"64/10"},
  {"id":"progressions-10","sec":"quant","topic":"progressions","pattern":"word-problems","d":"Medium","q":"Ravi starts a job at **₹30,000** a year with a fixed rise of **₹2,000** every year. How much does he earn in total over the first **10 years**?","opts":["₹4,00,000","₹3,00,000","₹3,90,000","₹7,80,000"],"ans":2,"time":75,"sol":["AP with a = 30,000, d = 2,000, n = 10","S = 10/2 × [60,000 + 9 × 2,000] = 5 × 78,000","= **₹3,90,000**"],"short":"Average of first and last (30,000 and 48,000) is 39,000; × 10.","trap":"Using n instead of n − 1 for the number of rises.","why":["Used 10 increments instead of 9","Ignored the annual rises",null,"Forgot the ½"],"calc":"5*(60000+9*2000)"},
  {"id":"logarithms-02","sec":"quant","topic":"logarithms","pattern":"laws","d":"Easy","q":"What is the value of log₁₀ 25 + log₁₀ 4?","opts":["2","100","29","1"],"ans":0,"time":35,"sol":["log a + log b = log (ab)","log₁₀ (25 × 4) = log₁₀ 100 = **2**"],"short":"A sum of logs of the same base is the log of the product.","trap":"Adding 25 + 4 inside the log is not allowed.","why":[null,"Forgot to take the log of the product","Added 25 and 4","Counted only one zero in 100"],"calc":"Math.log10(25*4)"},
  {"id":"logarithms-03","sec":"quant","topic":"logarithms","pattern":"change-of-base","d":"Easy","q":"Find the value of log₉ 27.","opts":["2/3","3/2","3","1/2"],"ans":1,"time":40,"sol":["Write both as powers of 3: 9 = 3², 27 = 3³","log₉ 27 = 3 log 3 ÷ 2 log 3 = **3/2**"],"short":"log_(aᵐ)(aⁿ) = n/m.","trap":"Writing 2/3 by flipping the ratio.","why":["Inverted the ratio (that is log₂₇ 9)",null,"Divided 27 by 9","Used 9 = 3² but ignored the 27"],"calc":"3/2"},
  {"id":"logarithms-05","sec":"quant","topic":"logarithms","pattern":"change-of-base","d":"Medium","q":"Find the value of log₂ 16 × log₄ 8.","opts":["5.5","6","8","8/3"],"ans":1,"time":55,"sol":["log₂ 16 = 4","log₄ 8 = 3 ÷ 2 = 1.5 (8 = 2³, 4 = 2²)","4 × 1.5 = **6**"],"short":"Convert everything to base 2 first.","trap":"Evaluating log₄ 8 as if the base were 2.","why":["Added 4 + 1.5 instead of multiplying",null,"Took log₄ 8 as 2","Divided 4 by 1.5"],"calc":"4*1.5"},
  {"id":"logarithms-07","sec":"quant","topic":"logarithms","pattern":"log-equations","d":"Medium","q":"Solve for x: log₂ x + log₂ (x − 2) = 3.","opts":["4","−2","5","8"],"ans":0,"time":70,"sol":["x(x − 2) = 2³ = 8, so x² − 2x − 8 = 0","(x − 4)(x + 2) = 0, so x = 4 or −2","log₂ (−2) does not exist, so **x = 4**"],"short":"Merge into one log, convert to a power, then reject any root that makes an argument ≤ 0.","trap":"Keeping x = −2.","why":[null,"Extraneous root: x must be greater than 2","Added x + (x − 2) = 8 instead of multiplying","Copied 2³ = 8 as the answer for x"],"calc":"1+sqrt(9)"},
  {"id":"logarithms-06","sec":"quant","topic":"logarithms","pattern":"number-of-digits-via-log","d":"Medium","q":"Using log₁₀ 2 = 0.3010, find the number of digits in 2⁶⁴.","opts":["19","21","20","64"],"ans":2,"time":60,"sol":["log₁₀ 2⁶⁴ = 64 × 0.3010 = 19.264","Digits = integer part + 1 = **20**"],"short":"Digits = floor(n log₁₀ a) + 1.","trap":"Using the integer part itself as the digit count.","why":["Forgot to add 1 to the integer part","Rounded 19.26 up and then added 1",null,"Took the exponent as the digit count"],"calc":"Math.floor(64*0.3010)+1"},
  {"id":"number-series-02","sec":"quant","topic":"number-series","pattern":"multiplicative","d":"Easy","q":"Find the next number: 3, 6, 12, 24, 48, ?","opts":["72","60","192","96"],"ans":3,"time":30,"sol":["Each term is 2 × the one before","48 × 2 = **96**"],"short":"Constant ratio of 2.","trap":"Using the last gap as a step.","why":["Added 24 (last gap) instead of doubling","Added 12","Multiplied by 4",null],"calc":"48*2"},
  {"id":"number-series-04","sec":"quant","topic":"number-series","pattern":"differences","d":"Medium","q":"Find the next number: 4, 6, 10, 18, 34, ?","opts":["68","50","66","58"],"ans":2,"time":55,"sol":["Differences: 2, 4, 8, 16 (each doubles)","Next difference 32, so 34 + 32 = **66**","(Also: each term = 2 × previous − 2.)"],"short":"Gaps that double: next gap is 32.","trap":"Doubling the last term without the −2.","why":["Doubled 34","Added the last gap of 16",null,"Added 24"],"calc":"34+32"},
  {"id":"number-series-05","sec":"quant","topic":"number-series","pattern":"mixed","d":"Medium","q":"Find the next number: 2, 5, 14, 41, 122, ?","opts":["366","365","364","368"],"ans":1,"time":65,"sol":["5 = 2×3 − 1, 14 = 5×3 − 1, 41 = 14×3 − 1, 122 = 41×3 − 1","Next = 122 × 3 − 1 = **365**","(Gaps 3, 9, 27, 81, 243 agree.)"],"short":"Try × a ± b; check with the gaps 3, 9, 27…","trap":"Using × 3 and forgetting the −1.","why":["Used × 3 only",null,"Used × 3 − 2","Used × 3 + 2"],"calc":"122*3-1"},
  {"id":"number-series-06","sec":"quant","topic":"number-series","pattern":"two-interleaved-series","d":"Medium","q":"Find the next number: 2, 3, 4, 6, 8, 12, 16, ?","opts":["24","18","20","32"],"ans":0,"time":65,"sol":["Odd places: 2, 4, 8, 16 (× 2)","Even places: 3, 6, 12, then **24** (× 2)","The 8th term belongs to the even series."],"short":"Split into two series: positions 1, 3, 5, 7 and 2, 4, 6, 8.","trap":"Continuing the first series instead of the second.","why":[null,"Added 2 to 16","Added 4 to 16","Doubled 16, ignoring the alternation"],"calc":"12*2"},
  {"id":"number-series-09","sec":"quant","topic":"number-series","pattern":"wrong-number","d":"Hard","q":"One number in this series is wrong. Which one? 3, 8, 15, 24, 35, 47, 63","opts":["24","47","35","63"],"ans":1,"time":80,"sol":["The terms follow n² − 1: 3, 8, 15, 24, 35, 48, 63","The sixth term should be 7² − 1 = 48, but 47 is given","Wrong number: **47**"],"short":"Gaps 5, 7, 9, 11, 13, 15 should rise by 2.","trap":"Blaming 63 because it follows a big jump.","why":["It fits 5² − 1",null,"It fits 6² − 1","It fits 8² − 1"],"calc":"48-1"},
  {"id":"clocks-01","sec":"quant","topic":"clocks","pattern":"angle-at-a-time","d":"Easy","q":"What is the angle between the hour and minute hands at 7:30?","opts":["30","315","15","45"],"ans":3,"time":45,"sol":["θ = |30H − 5.5M| = |210 − 165|","= **45°**"],"short":"θ = |30H − 5.5M|.","trap":"Putting the hour hand exactly on 7 at half past.","why":["Ignored the hour hand's drift: placed it exactly on 7","Gave the reflex angle","Used only the hour hand's drift of 15°",null],"calc":"Math.abs(30*7-5.5*30)"},
  {"id":"clocks-05","sec":"quant","topic":"clocks","pattern":"coinciding-opposite-right-angle","d":"Medium","q":"At how many minutes past 4 do the hour and minute hands first coincide after 4:00?","opts":["20","24","21 9/11","22"],"ans":2,"time":65,"sol":["Coincide when 5.5 M = 30 H = 120","M = 120 ÷ 5.5 = 240/11","= **21 9/11 minutes** past 4"],"short":"Between H and H+1 the hands coincide at 60H/11 minutes past H.","trap":"Forgetting that the hour hand keeps moving.","why":["Put the minute hand on the hour hand's starting mark (4)","Multiplied 6 × 4",null,"Rounded the answer up"],"calc":"240/11"},
  {"id":"clocks-03","sec":"quant","topic":"clocks","pattern":"gaining-and-losing-clocks","d":"Easy","q":"A clock gains 4 minutes every hour. It is set right at 8 AM. By how many minutes is it ahead at 4 PM the same day?","opts":["32","28","36","4"],"ans":0,"time":40,"sol":["Time elapsed = 8 hours","Gain = 8 × 4 = **32 minutes**"],"short":"Gain per hour × hours elapsed.","trap":"Counting the hours from 8 to 4 wrongly.","why":[null,"Counted 7 hours instead of 8","Counted 9 hours","Gave the gain of a single hour"],"calc":"8*4"},
  {"id":"clocks-06","sec":"quant","topic":"clocks","pattern":"clock-in-a-mirror","d":"Medium","q":"A clock seen in a mirror appears to show 3:40. What is the actual time?","opts":["9:20","8:40","3:20","8:20"],"ans":3,"time":45,"sol":["Real time = 11:60 − mirror time","11:60 − 3:40 = **8:20**"],"short":"Subtract the mirror time from 11:60 (or 12:00).","trap":"Using 12:00 on the hour and forgetting to borrow.","why":["Subtracted from 13:00 instead of 12:00","Changed the hour but kept the minutes","Changed only the minutes",null],"check":"(11*60+60)-(3*60+40)===8*60+20"},
  {"id":"clocks-08","sec":"quant","topic":"clocks","pattern":"how-many-times-a-day","d":"Hard","q":"How many times in a full day (24 hours) are the hands of a clock at right angles to each other?","opts":["22","24","44","48"],"ans":2,"time":90,"sol":["In 12 hours the minute hand gains 11 full turns on the hour hand","Each turn gives 2 right angles, so 22 in 12 hours","In 24 hours: **44**"],"short":"11 relative turns per 12 hours, 2 right angles each, doubled for the day.","trap":"Counting 2 per hour gives 48 and misses that the hands only gain 22 turns in a day.","why":["Counted only 12 hours","Counted twice per hour",null,"Counted 4 per hour"],"calc":"1440*5.5/360*2"},
  {"id":"calendars-01","sec":"quant","topic":"calendars","pattern":"odd-days-and-leap-years","d":"Easy","q":"How many odd days are there in 100 years?","opts":["0","2","5","1"],"ans":2,"time":40,"sol":["100 years have 24 leap years (the 100th is not leap) and 76 ordinary years","Odd days = 76 × 1 + 24 × 2 = 124, and 124 ÷ 7 leaves **5**"],"short":"Memorise: 100 yrs → 5, 200 → 3, 300 → 1, 400 → 0 odd days.","trap":"Counting 25 leap years.","why":["Took 100 years as a whole number of weeks","That is the figure for 200 years",null,"That is the figure for an ordinary year"],"calc":"(100*365+24)%7"},
  {"id":"calendars-02","sec":"quant","topic":"calendars","pattern":"n-days-after-monday","d":"Easy","q":"Today is Wednesday. What day of the week will it be 100 days from today?","opts":["Thursday","Saturday","Wednesday","Friday"],"ans":3,"time":40,"sol":["100 = 14 × 7 + 2, so 2 odd days","Wednesday + 2 = **Friday**"],"short":"Divide by 7 and move forward by the remainder.","trap":"Using the quotient instead of the remainder.","why":["Counted 99 days","Added 3 odd days","Took 100 days as a whole number of weeks",null],"check":"[\"Sunday\",\"Monday\",\"Tuesday\",\"Wednesday\",\"Thursday\",\"Friday\",\"Saturday\"][(3+100)%7]===\"Friday\""},
  {"id":"calendars-04","sec":"quant","topic":"calendars","pattern":"day-of-the-week-for","d":"Medium","q":"1 January 2001 was a Monday. What day of the week was 1 January 2025?","opts":["Wednesday","Tuesday","Thursday","Monday"],"ans":0,"time":70,"sol":["From 1 Jan 2001 to 1 Jan 2025 = 24 years, with leap years 2004, 2008, 2012, 2016, 2020, 2024 (6 leaps)","Odd days = 24 + 6 = 30, and 30 mod 7 = 2","Monday + 2 = **Wednesday**"],"short":"Each year adds 1 odd day, each leap year one more.","trap":"Missing the leap years 2004 and 2024.","why":[null,"Counted 5 leap years instead of 6","Counted 7 leap years","Assumed 24 years is a whole number of weeks"],"check":"[\"Sunday\",\"Monday\",\"Tuesday\",\"Wednesday\",\"Thursday\",\"Friday\",\"Saturday\"][new Date(2025,0,1).getDay()]===\"Wednesday\" && new Date(2001,0,1).getDay()===1"},
  {"id":"calendars-05","sec":"quant","topic":"calendars","pattern":"repeating-calendar-years","d":"Medium","q":"The calendar of 2018 will be the same as the calendar of which later year?","opts":["2024","2025","2029","2030"],"ans":2,"time":75,"sol":["2018 is an ordinary year, so odd days build up as 1 per year (2 for leap years)","From 1 Jan 2018 to 1 Jan 2029: 11 years including 3 leap years (2020, 2024, 2028) → 11 + 3 = 14 odd days, a whole number of weeks","The same calendar returns in **2029**"],"short":"Ordinary years repeat after 6, 11 or 12 years depending on the leap years in between.","trap":"Ignoring the leap years in the gap.","why":["A leap year cannot match an ordinary year","Started on the wrong weekday",null,"Added one odd day too many"],"check":"(() => { const lp = y => y%4===0&&(y%100!==0||y%400===0); for (let y=2019;y<2100;y++) if (lp(y)===lp(2018) && new Date(y,0,1).getDay()===new Date(2018,0,1).getDay()) return y===2029; })()"},
  {"id":"calendars-10","sec":"quant","topic":"calendars","pattern":"n-days-after-monday","d":"Hard","q":"15 August 2025 was a Friday. What day of the week will 26 January 2026 be?","opts":["Sunday","Tuesday","Monday","Friday"],"ans":2,"time":90,"sol":["Days remaining in Aug: 16, then Sep 30, Oct 31, Nov 30, Dec 31, plus 26 in Jan","Total = 16 + 30 + 31 + 30 + 31 + 26 = 164","164 = 23 × 7 + 3, so Friday + 3 = **Monday**"],"short":"Add up the days and use the remainder mod 7.","trap":"Counting the start date itself.","why":["Counted one day too few","Counted one day too many",null,"Assumed 164 days is a whole number of weeks"],"check":"[\"Sunday\",\"Monday\",\"Tuesday\",\"Wednesday\",\"Thursday\",\"Friday\",\"Saturday\"][new Date(2026,0,26).getDay()]===\"Monday\" && new Date(2025,7,15).getDay()===5 && Math.round((new Date(2026,0,26)-new Date(2025,7,15))/864e5)===164"},
  {"id":"statistics-02","sec":"quant","topic":"statistics","pattern":"mean-median-mode","d":"Easy","q":"Find the median of 7, 3, 9, 5, 11, 4.","opts":["7","6","5","6.5"],"ans":1,"time":40,"sol":["Sort: 3, 4, 5, 7, 9, 11","Middle two are 5 and 7, so median = (5 + 7) ÷ 2 = **6**"],"short":"Always sort first; with an even count average the middle pair.","trap":"Taking the middle of the unsorted list.","why":["Did not sort: averaged the middle pair 9 and 5",null,"Took the lower middle value","Gave the mean instead"],"calc":"(5+7)/2"},
  {"id":"statistics-04","sec":"quant","topic":"statistics","pattern":"mean-median-mode","d":"Medium","q":"The average of 5 numbers is 24. If one of them, 30, is removed, what is the average of the remaining numbers?","opts":["22.5","24","18","21"],"ans":0,"time":50,"sol":["Total = 5 × 24 = 120","Remaining total = 120 − 30 = 90 over 4 numbers","Average = **22.5**"],"short":"Work with totals, then divide by the new count.","trap":"Dividing by the old count.","why":[null,"Assumed the average does not change","Divided the remaining total by 5","Averaged 24 and 18"],"calc":"(5*24-30)/4"},
  {"id":"statistics-05","sec":"quant","topic":"statistics","pattern":"range-and-standard-deviation-basics","d":"Medium","q":"In a data set the smallest value is 18 and the range is 47. If every value is increased by 10, what is the new largest value?","opts":["65","75","57","47"],"ans":1,"time":55,"sol":["Largest = smallest + range = 18 + 47 = 65","Adding 10 to every value: 65 + 10 = **75**"],"short":"Largest = smallest + range; a shift moves every value, not the range.","trap":"Treating the range as the maximum.","why":["Forgot to add the 10",null,"Added 10 to the range only","Used the range as the largest value"],"calc":"18+47+10"},
  {"id":"statistics-06","sec":"quant","topic":"statistics","pattern":"effect-of-adding-multiplying-every","d":"Medium","q":"The mean of 10 observations is 12. Each observation is multiplied by 4 and then 2 is subtracted. What is the new mean?","opts":["48","50","40","46"],"ans":3,"time":45,"sol":["New mean = 4 × 12 − 2","= **46**"],"short":"The mean follows the same arithmetic as each value.","trap":"Applying the operations in the wrong order.","why":["Forgot to subtract 2","Added 2 instead of subtracting","Subtracted 2 first, then multiplied",null],"calc":"4*12-2"},
  {"id":"statistics-07","sec":"quant","topic":"statistics","pattern":"range-and-standard-deviation-basics","d":"Medium","q":"Find the population standard deviation of 2, 4, 4, 4, 5, 5, 7, 9.","opts":["4","2.14","2","1.5"],"ans":2,"time":80,"sol":["Mean = 40 ÷ 8 = 5","Squared deviations: 9, 1, 1, 1, 0, 0, 4, 16, sum 32","Variance = 32 ÷ 8 = 4, so SD = **2**"],"short":"SD = √(mean of squared deviations).","trap":"Stopping at the variance.","why":["Gave the variance","Divided by n − 1 (sample SD)",null,"Gave the mean absolute deviation"],"calc":"Math.sqrt((9+1+1+1+0+0+4+16)/8)"},
  {"id":"sets-ds-01","sec":"quant","topic":"sets-ds","pattern":"two-set","d":"Easy","q":"In a group of 100 students, 60 like tea, 45 like coffee and 20 like both. How many like neither?","opts":["15","5","25","40"],"ans":0,"time":45,"sol":["At least one = 60 + 45 − 20 = 85","Neither = 100 − 85 = **15**"],"short":"n(A ∪ B) = n(A) + n(B) − n(A ∩ B).","trap":"Forgetting to subtract the overlap once.","why":[null,"Subtracted 60 + 45 − 100 ignoring the overlap","Gave coffee-only","Gave tea-only"],"calc":"100-(60+45-20)"},
  {"id":"sets-ds-05","sec":"quant","topic":"sets-ds","pattern":"three-set","d":"Medium","q":"In a class of 60, 30 play cricket, 25 play football and 20 play hockey. 10 play cricket and football, 8 play football and hockey, 6 play cricket and hockey, and 3 play all three. How many play none of the games?","opts":["9","3","12","6"],"ans":3,"time":80,"sol":["Union = 30 + 25 + 20 − 10 − 8 − 6 + 3 = 54","None = 60 − 54 = **6**"],"short":"Inclusion–exclusion: singles − pairs + triple.","trap":"Forgetting the + triple term.","why":["Forgot to add back the 3 who play all","Gave the all-three count","Subtracted the 3 instead of adding",null],"calc":"60-(30+25+20-10-8-6+3)"},
  {"id":"sets-ds-07","sec":"quant","topic":"sets-ds","pattern":"max-and-min-overlap","d":"Medium","q":"In a group of 200 people, 140 speak Hindi and 120 speak English. What is the least possible number who speak both?","opts":["120","20","60","80"],"ans":2,"time":55,"sol":["Least overlap happens when everyone speaks at least one language","Both = 140 + 120 − 200 = **60**"],"short":"Minimum overlap = A + B − Total.","trap":"Quoting the maximum, the smaller set.","why":["That is the maximum possible","Subtracted 200 − 180",null,"Took 200 − 120"],"calc":"140+120-200"},
  {"id":"sets-ds-06","sec":"quant","topic":"sets-ds","pattern":"data-sufficiency-with-the-standard","d":"Medium","q":"**What is the number of students in a class?**\n**I.** 40% of the students are girls and there are 18 girls.\n**II.** There are 27 boys in the class.\n\nWhich of the following is correct?","opts":["I alone","II alone","Either alone","Both together"],"ans":0,"time":70,"sol":["I: 0.4 × N = 18, so N = 45, which is a single answer","II: 27 boys, but the number of girls is unknown","Only **I alone** is sufficient"],"short":"Test each statement alone first; only then combine.","trap":"Combining the statements when one is already enough.","why":[null,"II gives only the boys, with no ratio to the total","II is not enough by itself","I is already enough by itself"],"check":"(() => { const r=[...Array(300).keys()].slice(1); const I=r.filter(n=>2*n===90); const II=r.filter(n=>n>=27); return I.length===1 && II.length>1; })()"},
  {"id":"sets-ds-04","sec":"quant","topic":"sets-ds","pattern":"two-set","d":"Medium","q":"Among 120 employees, 75 know Java, 60 know Python and 25 know neither. How many know exactly one of the two languages?","opts":["95","55","40","35"],"ans":1,"time":70,"sol":["At least one = 120 − 25 = 95","Both = 75 + 60 − 95 = 40","Exactly one = 95 − 40 = **55**"],"short":"Exactly one = at least one − both.","trap":"Answering 'at least one' instead of 'exactly one'.","why":["Gave those who know at least one",null,"Gave those who know both","Gave Java-only"],"calc":"(120-25)-(75+60-(120-25))"},
  {"id":"pct-of-01","sec":"quant","topic":"percentages","pattern":"percent-of","d":"Easy","q":"What is **37.5%** of 640?","opts":["24","400","240","2,400"],"ans":2,"time":35,"sol":["37.5% = 3/8","3/8 × 640 = 80 × 3 = **240**"],"short":"Learn the eighths: 12.5, 25, 37.5, 50, 62.5, 75, 87.5 are 1/8 to 7/8.","trap":"Slipping a decimal place gives 24 or 2,400.","why":["Decimal slip: used 3.75%","Used 5/8 instead of 3/8",null,"Decimal slip: used 375%"],"calc":"0.375*640"},
  {"id":"pct-change-02","sec":"quant","topic":"percentages","pattern":"pct-change","d":"Easy","q":"The price of a pen falls from ₹25 to ₹20. What is the percentage decrease?","opts":["5%","20%","25%","80%"],"ans":1,"time":35,"sol":["Fall = 25 − 20 = 5","5 ÷ 25 × 100 = **20%**"],"short":"Fall ÷ old: 5/25 = 1/5 = 20%.","trap":"Dividing by the new price (5/20 = 25%).","why":["Used the rupee fall as the percent",null,"Divided the fall by the new price","Gave new price as % of old"],"calc":"(25-20)/25*100"},
  {"id":"pct-succ-03","sec":"quant","topic":"percentages","pattern":"successive-change","d":"Easy","q":"A number is increased by **50%** and the result is then decreased by **50%**. The final value is what percent of the original?","opts":["100%","25%","75%","50%"],"ans":2,"time":30,"sol":["Factor = 1.5 × 0.5 = 0.75","The final value is **75%** of the original"],"short":"Half of one-and-a-half.","trap":"Assuming the changes cancel.","why":["Assumed the changes cancel","Gave the loss, not the final value",null,"Counted only the fall"],"calc":"1.5*0.5*100"},
  {"id":"pct-elect-02","sec":"quant","topic":"percentages","pattern":"elections","d":"Easy","q":"In an election between two candidates, one candidate got **45%** of the votes and lost by **2,000** votes. How many votes were polled in total?","opts":["≈ 4,444","20,000","40,000","10,000"],"ans":1,"time":40,"sol":["Winner got 55%, so margin = 55 − 45 = 10% of total","Total = 2,000 ÷ 0.10 = **20,000**"],"short":"Margin = 10% of total, so total = margin × 10.","trap":"The margin is 10% of the total, not 55% − 45% = 10 of one candidate's share.","why":["Divided the margin by 45% only",null,"Divided the margin by 5%, not 10%","Treated the margin as 20% of the total"],"calc":"2000/0.1"},
  {"id":"pct-back-04","sec":"quant","topic":"percentages","pattern":"back-calc","d":"Easy","q":"A bag of sugar became **20% lighter** after spillage and now weighs **8 kg**. What was its original weight?","opts":["9.6 kg","6.4 kg","2 kg","10 kg"],"ans":3,"time":35,"sol":["8 kg is 80% of the original","Original = 8 ÷ 0.8 = **10 kg**"],"short":"80% = 8, so 10% = 1 and 100% = 10.","trap":"Go from the 80% that is left back to 100%.","why":["Added 20% to 8 kg","Took 20% off 8 kg","Gave the amount spilled",null],"calc":"8/0.8"}
]);
